CREATE TABLE IF NOT EXISTS stewardship_communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, community_type text NOT NULL, country_code text, locality text, recognition_status text NOT NULL DEFAULT 'Unverified', customary_authority_reference text, representative_reference text, contact_reference text, evidence_reference text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS stewardship_rights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid REFERENCES stewardship_communities(id) ON DELETE CASCADE, right_type text NOT NULL, asset_reference text, geographic_reference text, legal_basis text, customary_basis text, priority_status text NOT NULL DEFAULT 'Unverified', evidence_reference text, verification_status text NOT NULL DEFAULT 'Unverified', status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS stewardship_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid REFERENCES stewardship_communities(id), claimant_reference text NOT NULL, claim_type text NOT NULL, asset_reference text, description text NOT NULL, filed_date date NOT NULL DEFAULT current_date, evidence_reference text, review_status text NOT NULL DEFAULT 'Open', resolution_reference text, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS stewardship_consultations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid REFERENCES stewardship_communities(id), project_reference text NOT NULL, consultation_type text NOT NULL, required_standard text, notice_date date, meeting_date date, participants_reference text, information_disclosed text, concerns_recorded text, consent_required boolean NOT NULL DEFAULT false, consent_status text NOT NULL DEFAULT 'Not Required', evidence_reference text, status text NOT NULL DEFAULT 'Planned');
CREATE TABLE IF NOT EXISTS stewardship_benefit_agreements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid REFERENCES stewardship_communities(id), project_reference text NOT NULL, benefit_type text NOT NULL, description text NOT NULL, value_reference text, distribution_method text, duration text, approval_reference text, evidence_reference text, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS stewardship_grievances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid REFERENCES stewardship_communities(id), project_reference text, complainant_reference text, grievance_type text NOT NULL, description text NOT NULL, filed_date date NOT NULL DEFAULT current_date, severity text NOT NULL DEFAULT 'Medium', remediation text, resolved_date date, independent_review boolean NOT NULL DEFAULT false, evidence_reference text, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS stewardship_safeguards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_reference text NOT NULL, safeguard_type text NOT NULL, standard_reference text, assessment_reference text, mitigation text, residual_risk text, reviewer_reference text, evidence_reference text, status text NOT NULL DEFAULT 'Required');
CREATE TABLE IF NOT EXISTS stewardship_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_reference text NOT NULL, review_type text NOT NULL, reviewer_reference text NOT NULL, independence_status text, scope text NOT NULL, findings text, conditions text, evidence_reference text, decision text NOT NULL DEFAULT 'Pending', reviewed_date date, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS stewardship_clearances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_reference text NOT NULL UNIQUE, community_rights_status text NOT NULL DEFAULT 'Pending', consultation_status text NOT NULL DEFAULT 'Pending', consent_status text NOT NULL DEFAULT 'Pending', benefit_sharing_status text NOT NULL DEFAULT 'Pending', safeguards_status text NOT NULL DEFAULT 'Pending', independent_review_status text NOT NULL DEFAULT 'Pending', legal_review_status text NOT NULL DEFAULT 'Pending', clearance_decision text NOT NULL DEFAULT 'Not Cleared', decision_basis text, decision_reference text, issued_date date, expiry_date date, evidence_reference text, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS stewardship_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid NOT NULL, evidence_type text NOT NULL, reference text NOT NULL, source_description text, verification_method text, verified_by text, verified_date date, hash_reference text, status text NOT NULL DEFAULT 'Unverified', notes text, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO stewardship_communities(name,community_type,recognition_status,status) SELECT 'No community record entered','Placeholder','Not Applicable','System Placeholder' WHERE NOT EXISTS (SELECT 1 FROM stewardship_communities);